with RecursiveReplies as (
    select 
        p.Id,
        p.ParentId,
        p.CreationDate,
        0 as Level
    from Posts p 
    where p.PostTypeId = 2 and p.ParentId is not null

    union all

    select 
        r.Id,
        r.ParentId,
        r.CreationDate,
        rr.Level + 1 as Level
    from Posts r
    inner join RecursiveReplies rr on r.ParentId = rr.Id
    where r.PostTypeId = 2
),
